import {Art} from './art.js';
import {SAVE_KEY,DAYS,SHOP,freshSave,validateSave,reward,weekBonus,purchase,fireSteps,safeText} from './core.js';

const $=s=>document.querySelector(s), canvas=$('#world'),ctx=canvas.getContext('2d'),art=new Art(ctx);
const dialog=$('#modal'),content=$('#modal-content');
let save=freshSave(),database=null,screen='map',hits=[],selected=null,pointer=null,drag=null,time=0,last=0,animation=null,celebrating=false,liveAction=false,dirtyTimer=null,speechTimer=null,toastTimer=null,deferredInstall=null;
let player={x:570,y:450,target:null},parkMode='ball',color='#db966d',ball={x:690,y:430,vx:0,vy:0},kite={x:660,y:230},rainbow=[],note=0,fireRoute=0,hydration=0;
const colors=['#db966d','#e7bc67','#91b1a2','#a4a9ca','#c79db0'];
const ICONS={fire:'♜',week:'▦',park:'♧',shop:'◇',map:'⌂',helmet:'◒',hose:'◎',cone:'△',book:'▰',bottle:'▥',apple:'●',water:'♧',seed:'✳',kite:'◇',flower:'✳',drum:'♫',car:'▰',ball:'●',block:'▣',brush:'╱'};
const dayData=[
 {name:'lunes',title:'La mochila del lunes',items:['book','bottle'],goal:'mochila',activity:'class',task:'Lleva el libro a la mesa. ¡Empieza un nuevo día!',result:'Preparamos la mochila y fuimos al colegio.'},
 {name:'martes',title:'Una merienda para compartir',items:['apple','bottle'],goal:'cesta',activity:'fruit',task:'Reparte una manzana a cada amigo. Una para cada uno.',result:'Fuimos al colegio y compartimos la merienda.'},
 {name:'miércoles',title:'Un cuento en la biblioteca',items:['book','bottle'],goal:'mochila',activity:'story',task:'Ordena el cuento: primero la semilla, después la regadera y al final la flor.',result:'Fuimos al colegio y descubrimos un cuento.'},
 {name:'jueves',title:'El huerto de la clase',items:['water','seed'],goal:'carrito',activity:'garden',task:'Lleva la regadera a cada planta. Mira cómo crecen.',result:'Fuimos al colegio y cuidamos el huerto.'},
 {name:'viernes',title:'La pequeña banda',items:['drum','bottle'],goal:'mochila',activity:'music',task:'Escucha y repite el ritmo. Puedes tocar los instrumentos.',result:'Fuimos al colegio y tocamos una canción.'},
 {name:'sábado',title:'La cometa del sábado',items:['kite','bottle'],goal:'cesta',activity:'kite',task:'Guía la cometa hacia las tres nubes pequeñas.',result:'Hoy no había colegio. Hicimos volar una cometa.'},
 {name:'domingo',title:'Un picnic antes del lunes',items:['apple','book'],goal:'cesta',activity:'picnic',task:'Prepara la merienda y deja la mochila lista para mañana.',result:'Disfrutamos del picnic y preparamos el lunes.'},
];

function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function announce(text,automatic=true){const changed=$('#guide-message').textContent!==text;$('#guide-message').textContent=text;if(save.settings.sound&&(changed||!automatic)){clearTimeout(speechTimer);speechTimer=setTimeout(()=>speak(text),automatic?260:0);}}
function speak(text){if(!save.settings.sound||!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='es-ES';u.rate=.86;u.pitch=1.05;const voices=window.speechSynthesis.getVoices();const voice=voices.find(v=>v.lang==='es-ES')||voices.find(v=>v.lang.startsWith('es'));if(voice)u.voice=voice;window.speechSynthesis.speak(u);}
let audio;
function ping(freq=600,duration=.13){if(!save.settings.sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audio.currentTime);g.gain.setValueAtTime(.07,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function closeDialog(){dialog.close();}
function modal(html){content.innerHTML=`<button class="close-modal" aria-label="Cerrar">×</button>${html}`;content.querySelector('.close-modal').onclick=closeDialog;if(!dialog.open)dialog.showModal();}
function initDatabase(){return new Promise(resolve=>{if(!window.indexedDB)return resolve();const req=indexedDB.open('villachispa',1);req.onupgradeneeded=()=>req.result.createObjectStore('save');req.onsuccess=()=>{database=req.result;resolve();};req.onerror=()=>resolve();req.onblocked=()=>resolve();});}
async function load(){await initDatabase();let raw;try{raw=localStorage.getItem(SAVE_KEY);}catch{}if(raw)try{save=validateSave(JSON.parse(raw));return;}catch{toast('No pudimos leer la partida anterior. Puedes importar una copia.');}if(database)await new Promise(resolve=>{const req=database.transaction('save').objectStore('save').get('profile');req.onsuccess=()=>{if(req.result)try{save=validateSave(req.result);}catch{}resolve();};req.onerror=()=>resolve();});}
function persist(){clearTimeout(dirtyTimer);try{localStorage.setItem(SAVE_KEY,JSON.stringify(save));}catch{$('#connection-status').textContent='No se pudo guardar. Exporta una copia.';}if(database)try{const tx=database.transaction('save','readwrite');tx.objectStore('save').put(structuredClone(save),'profile');tx.onerror=()=>{$('#connection-status').textContent='Exporta una copia para conservar la partida.';};}catch{}updateBalance();}
function laterSave(){clearTimeout(dirtyTimer);dirtyTimer=setTimeout(persist,200);}
function updateBalance(){$('#balance').textContent=save.coins;$('#age-button').innerHTML=`${save.age} años <span>⌄</span>`;document.body.classList.toggle('quiet',save.settings.quiet);$('#sound-button').textContent=save.settings.sound?'♪':'♫';$('#sound-button').setAttribute('aria-label',save.settings.sound?'Desactivar voz y sonidos':'Activar voz y sonidos');}
function action(label,fn,{icon='→',detail='',primary=false,disabled=false}={}){const b=document.createElement('button');b.className=`action-button${primary?' primary':''}`;b.disabled=disabled;b.setAttribute('aria-label',label);b.innerHTML=`<span class="action-icon" aria-hidden="true">${icon}</span><span>${safeText(label)}${detail?`<small>${safeText(detail)}</small>`:''}</span><span class="arrow" aria-hidden="true">↗</span>`;b.onclick=()=>{if(!animation&&!dialog.open)fn();};$('#action-list').append(b);return b;}
function header(eyebrow,title,description,badge){$('#eyebrow').textContent=eyebrow;$('#page-title').textContent=title;$('#page-description').textContent=description;$('#world-badge').innerHTML=`<span></span>${safeText(badge)}`;}
function sceneUI(){selected=null;drag=null;pointer=null;$('#action-list').replaceChildren();$('#scene-progress').hidden=!['fire','week'].includes(screen);$('#scene-caption').textContent='También puedes tocar los objetos del escenario';$('#guide-footer').innerHTML='<span class="small-star">✳</span> Sin prisas. Puedes pedir ayuda.';document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===screen));}
function navigate(where){if(animation)return;if(dialog.open)dialog.close();window.speechSynthesis?.cancel();liveAction=false;if(save.active&&where!==save.active.type){save.checkpoints[save.active.type]=structuredClone(save.active);save.active=null;persist();}screen=where;selected=null;player.target=null;animation=null;sceneUI();if(where==='map')mapUI();if(where==='fire')startFire();if(where==='week')startWeek();if(where==='park')parkUI();if(where==='shop'){screen='map';mapUI();shop();}render();}
function mapUI(){header('TU PEQUEÑO GRAN MUNDO','Hoy empieza una aventura.','Un pueblo lleno de cosas por hacer. ¿Adónde vamos?','TU PUEBLO ESTÁ DESPIERTO');announce('¡Hola! Soy Luma. Podemos ayudar a los bomberos o descubrir los días de la semana. Tú eliges.');$('#scene-progress').hidden=true;action('Bomberos al rescate',()=>navigate('fire'),{icon:ICONS.fire,detail:save.completed.fire?'Volver a ayudar · +3 monedas':'Preparar, conducir y ayudar · +10',primary:true});action('Una semana con Luma',()=>navigate('week'),{icon:ICONS.week,detail:`Continuar por el ${DAYS[save.weekDay]}`});action('Jugar en mi parque',()=>navigate('park'),{icon:ICONS.park,detail:'Construye, pinta y juega libremente'});action('La tienda de juguetes',shop,{icon:ICONS.shop,detail:'Cosas bonitas que puedes usar'});if(save.active)$('#guide-footer').innerHTML='<span class="small-star">✳</span> Tu aventura se ha quedado guardada.';}
function stepProgress(count,index){$('#scene-progress').innerHTML=Array.from({length:count},(_,i)=>`<span class="${i<index?'done':i===index?'current':''}"></span>`).join('');}
function current(){return save.active;}
function addEvidence(text){save.evidence.push({text,age:save.age,assisted:!!save.active?.assisted,date:new Date().toISOString()});save.evidence=save.evidence.slice(-60);}
function startFire(){if(!current()||current().type!=='fire'){save.active=save.checkpoints.fire||{type:'fire',stage:0,picked:[],water:[0,0,0],run:save.fireRun,level:save.age,assisted:false};delete save.checkpoints.fire;persist();}fireUI();}
function fireStep(){return fireSteps(current()?.level||save.age)[current()?.stage||0];}
function stageNext(){if(animation)return;ping(780);current().stage++;current().picked=[];current().attempts=0;selected=null;persist();if(screen==='fire'&&current().stage>=fireSteps(current().level).length){finishFire();return;}if(screen==='week'&&current().stage>=3){finishDay();return;}screen==='fire'?fireUI():weekUI();}
function advanceSoon(){if(animation)return;animation={kind:'wait',elapsed:0,duration:.45,callback:()=>{animation=null;stageNext();}};}
function fireItems(){return current().level<=3?['helmet','hose']:['helmet','hose','cone'];}
const names={helmet:'casco',hose:'manguera',cone:'cono',book:'libro',bottle:'botella',apple:'manzana',water:'regadera',seed:'semillas',kite:'cometa',drum:'tambor'};
function fireUI(){sceneUI();const a=current(),step=fireStep();header('LA BASE DE LOS AYUDANTES','Un pequeño gran rescate.','Prepara el camión y ayuda al equipo de bomberos.','AVENTURA · BOMBEROS');stepProgress(fireSteps(a.level).length,a.stage);const texts={equipo:'El equipo necesita el casco y la manguera. Llévalos al camión. Puedes arrastrar o tocar un objeto y después el camión.',depósito:'Antes de salir, llenamos el depósito. Sube la palanca hasta la marca.',camino:a.level>=5?'El puente de madera está cerrado. Elige el camino que pasa por el puente de piedra.':'¡Todo preparado! Toca el final del camino y acompaña al camión hasta la granja.',animales:'El equipo ya ha sacado a los animales. Guía a cada uno hasta el corral seguro.',agua:'Desde aquí estamos a salvo. Orienta el agua hacia cada llama para apagarla.',cuidado:'¡Buen trabajo! Lleva agua a cada animal y ayúdalos a estar tranquilos.',recuerdos:'¿Qué hicimos primero? Ordena los recuerdos: preparar el camión, llegar a la granja y cuidar a los animales.'};announce(texts[step]);
 if(step==='equipo'){for(const id of fireItems().filter(id=>!a.picked.includes(id)))action(`Coger ${names[id]}`,()=>choose(id),{icon:ICONS[id],detail:'Después toca el camión'});action('Colocar en el camión',()=>putEquipment(),{icon:'↗',primary:true,disabled:!selected});}
 if(step==='depósito')action('Subir la palanca',()=>fillTank(),{icon:'↑',primary:true,detail:'También puedes arrastrarla hacia arriba'});
 if(step==='camino'){if(a.level>=5){action('Puente de piedra',()=>driveFire(0),{icon:'↗',primary:true,detail:'Camino abierto'});action('Puente de madera',()=>{conceptHint('Ese puente está cerrado. Busquemos otro camino.');},{icon:'⌁',detail:'Hay una señal de cierre'});}else action('Conducir hasta la granja',()=>driveFire(0),{icon:'↗',primary:true,detail:'Sigue la carretera sin prisas'});}
 if(step==='animales'){for(let i=0;i<animalCount();i++)if(!a.picked.includes(`animal${i}`))action(`Acompañar ${i?'gatito':'oveja'}`,()=>choose(`animal${i}`),{icon:'♡',detail:'Después toca el corral seguro'});action('Llevar al corral',()=>rescue(),{icon:'⌂',primary:true,disabled:!selected?.startsWith('animal')});}
 if(step==='agua'){for(let i=0;i<fireCount();i++)if((a.water[i]||0)<1)action(`Agua al foco ${i+1}`,()=>sprayTarget(i),{icon:'≈',primary:i===0,detail:'Orientar el chorro de agua'});}
 if(step==='cuidado'){for(let i=0;i<animalCount();i++)if(!a.picked.includes(`care${i}`))action(`Dar agua ${i?'al gatito':'a la oveja'}`,()=>careAnimal(i),{icon:'♡',primary:i===0});}
 if(step==='recuerdos'){const labels=['Preparar el camión','Llegar a la granja','Cuidar a los animales'];for(const i of [2,0,1])if(!a.picked.includes(`memory${i}`))action(labels[i],()=>memory(i),{icon:['♜','↗','♡'][i],detail:a.picked.length?'¿Y después?':'¿Qué hicimos primero?'});}
 $('#scene-caption').textContent={equipo:'Lleva el equipo al camión',depósito:'Arrastra la palanca hacia arriba',camino:'Sigue el camino de la granja',animales:'Del camino seguro al corral',agua:'Apunta al fuego desde la zona segura',cuidado:'Un poco de agua y mucho cuidado',recuerdos:'Primero, después y al final'}[step];}
function choose(id){selected=id;ping(420);if(screen==='fire')fireUI();else weekUI();selected=id; // sceneUI limpia la selección al reconstruir; restaura y habilita el destino.
 const buttons=[...$('#action-list').querySelectorAll('button')];const dest=buttons.find(b=>/Colocar en el camión|Llevar al corral|Guardar en|Colocar en|Repartir al/.test(b.textContent));if(dest)dest.disabled=false;toast(`Ahora elige dónde colocar ${names[id]||'el objeto'}.`);}
function putEquipment(){const a=current();if(!selected||!fireItems().includes(selected))return hint('Primero elige un objeto del equipo.');if(!a.picked.includes(selected)){a.picked.push(selected);ping();}selected=null;persist();if(fireItems().every(id=>a.picked.includes(id)))advanceSoon();else fireUI();}
function fillTank(){if(animation)return;hydration=0;animation={kind:'tank',elapsed:0,duration:1.3,callback:()=>{animation=null;stageNext();}};ping(450,.4);}
function driveFire(route){if(animation)return;fireRoute=route;animation={kind:'drive-fire',elapsed:0,duration:save.settings.quiet?1:3.5,callback:()=>{animation=null;stageNext();}};announce('Por el camino abierto, llegamos juntos a la granja.');}
function animalCount(){return current().level<=3?1:2;}
function fireCount(){return current().level<=3?2:3;}
function rescue(){if(!selected?.startsWith('animal'))return hint('Elige primero al animal que quieres acompañar.');const id=selected;selected=null;animation={kind:'rescue',id,elapsed:0,duration:save.settings.quiet?.4:1.2,callback:()=>{animation=null;if(!current().picked.includes(id))current().picked.push(id);persist();if(current().picked.length>=animalCount())advanceSoon();else fireUI();}};ping(570);}
function sprayTarget(i){if(animation||current().water[i]>=1)return;liveAction=false;animation={kind:'spray',index:i,elapsed:0,duration:1.2,callback:()=>{animation=null;current().water[i]=1;persist();if(current().water.slice(0,fireCount()).every(v=>v>=1))advanceSoon();else fireUI();}};}
function careAnimal(i){const id=`care${i}`;if(current().picked.includes(id))return;selected=null;ping(680);current().picked.push(id);persist();if(current().picked.length>=animalCount())advanceSoon();else fireUI();}
function memory(i){const a=current();if(i!==a.picked.length){conceptHint('Pensemos juntos. Antes de salir, preparamos el camión.');return;}a.picked.push(`memory${i}`);ping(600+i*130);persist();if(a.picked.length===3)advanceSoon();else fireUI();}
function finishFire(){const a=current(),res=reward(save,'fire',`fire-${a.run}`);addEvidence('Preparó el equipo y siguió la secuencia del rescate.');save.fireRun++;save.active=null;persist();showReward('¡La granja está tranquila!',res.amount,'Has preparado, acompañado y cuidado. Si hay fuego de verdad, aléjate y avisa a una persona adulta.',()=>navigate('map'));}
function conceptHint(text){current().attempts=(current().attempts||0)+1;if(current().attempts>=2)current().assisted=true;persist();hint(text);}
function hint(text){toast(text);speak(text);rainbow.push({x:600,y:300,life:1,kind:'hint'});}

function startWeek(){if(!current()||current().type!=='week'){save.active=save.checkpoints.week||{type:'week',stage:0,day:save.weekDay,picked:[],water:[0,0,0],run:save.weekRun,level:save.age,assisted:false};delete save.checkpoints.week;persist();}weekUI();}
function day(){return dayData[current()?.day??save.weekDay];}
function weekItems(){const items=[...day().items];if(current().level>=5&&!items.includes('apple'))items.push('apple');return items;}
function weekIsSchool(){return current().day<5&&!save.settings.holiday;}
function weekUI(){sceneUI();const a=current(),d=day();header('EL CALENDARIO DE LUMA',d.title,'Una semana se descubre viviendo cada día.','AVENTURA · LA SEMANA');stepProgress(3,a.stage);
 if(a.stage===0){announce(`Hoy es ${d.name}. ${a.day<5?(save.settings.holiday?'Es festivo y el colegio está cerrado. Preparamos una salida al parque.':'Vamos al colegio. Prepara lo que llevaremos. '):'Hoy disfrutamos de un día sin colegio. '}Guarda los objetos en ${d.goal==='mochila'?'la mochila':d.goal==='carrito'?'el carrito':'la cesta'}.`);for(const id of weekItems().filter(x=>!a.picked.includes(x)))action(`Coger ${names[id]}`,()=>choose(id),{icon:ICONS[id],detail:'Llévalo al recipiente'});action(`Guardar en ${d.goal==='mochila'?'la mochila':d.goal==='carrito'?'el carrito':'la cesta'}`,weekPack,{icon:'↓',primary:true,disabled:!selected});}
 if(a.stage===1){announce(weekIsSchool()?`Hoy es ${d.name}. La mochila está lista. Acompáñame al colegio.`:`Hoy es ${d.name}. ${a.day<5?'Es festivo. ':''}Acompáñame al parque por el camino.`);action(weekIsSchool()?'Caminar hasta el colegio':'Caminar hasta el parque',weekWalk,{icon:'↗',primary:true,detail:'Luma seguirá el sendero'});if(a.level>=5)action('Mirar el calendario',()=>hint(`Hoy es ${d.name}. Después llegará el ${DAYS[(a.day+1)%7]}.`),{icon:'▦'});}
 if(a.stage===2){announce(d.task);const act=d.activity;if(act==='class'){action('Coger el libro',()=>choose('book'),{icon:'▰'});action('Colocar en la mesa',weekTask,{icon:'↓',primary:true,disabled:selected!=='book'});}
 if(act==='fruit'){const n=a.level<=3?2:3;for(let i=0;i<n;i++)if(!a.picked.includes(`fruit${i}`))action(`Una manzana para ${['Luma','Nico','Sol'][i]}`,()=>weekTask(i),{icon:'●',primary:i===0});}
 if(act==='story'){for(const id of ['flower','seed','water'])if(!a.picked.includes(id))action(({seed:'Sembrar la semilla',water:'Regar la tierra',flower:'Crece la flor'})[id],()=>weekTask(id),{icon:ICONS[id]||'✳'});}
 if(act==='garden'){for(let i=0;i<(a.level<=3?2:3);i++)if(!a.picked.includes(`plant${i}`))action(`Regar la planta ${i+1}`,()=>weekTask(i),{icon:'♧',primary:i===0,detail:'También puedes llevar la regadera'});}
 if(act==='music'){action('Escuchar el ritmo',playRhythm,{icon:'♪'});for(let i=0;i<3;i++)action(['Tambor grave','Campana suave','Tambor agudo'][i],()=>weekTask(i),{icon:'♫'});}
 if(act==='kite'){for(let i=0;i<3;i++)if(!a.picked.includes(`cloud${i}`))action(`Volar hacia la nube ${i+1}`,()=>weekTask(i),{icon:'◇',primary:i===0});}
 if(act==='picnic'){const ids=['blanket','apple','backpack'];for(const id of ids)if(!a.picked.includes(id))action(({blanket:'Extender la manta',apple:'Repartir la merienda',backpack:'Preparar la mochila del lunes'})[id],()=>weekTask(id),{icon:id==='apple'?'●':'▰',primary:id==='blanket'});}
 }
 const strip=document.createElement('div');strip.className='week-strip';strip.setAttribute('aria-label',`Hoy es ${DAYS[a.day]}`);strip.innerHTML=DAYS.map((d,i)=>`<span class="${i===a.day?'today':save.completed[`week-${i}`]?'past':''}" title="${d}">${d.slice(0,3)}</span>`).join('');$('#action-list').append(strip);$('#scene-caption').textContent=a.stage===0?'Preparamos lo que necesitamos':a.stage===1?'Vamos por el sendero':d.task;}
function weekPack(){if(!selected||!weekItems().includes(selected))return hint('Elige un objeto y después el recipiente.');if(!current().picked.includes(selected))current().picked.push(selected);selected=null;ping();persist();if(weekItems().every(x=>current().picked.includes(x)))advanceSoon();else weekUI();}
function weekWalk(){if(animation)return;animation={kind:'week-walk',elapsed:0,duration:save.settings.quiet?.5:2.7,callback:()=>{animation=null;stageNext();if(day().activity==='music')playRhythm();}};}
function playRhythm(){const seq=current().level<=3?[0,1]:[0,1,2];seq.forEach((n,i)=>setTimeout(()=>{if(screen==='week'&&current()?.stage===2){ping([330,550,770][n],.25);rainbow.push({x:420+n*180,y:350,life:.9,kind:'note'});}},i*550));}
function weekTask(id){if(animation)return;const a=current(),act=day().activity;
 if(act==='class'){if(selected!=='book')return hint('Coge el libro y después toca la mesa.');a.picked.push('book');selected=null;}
 if(act==='fruit'){const key=`fruit${id}`;if(a.picked.includes(key))return;a.picked.push(key);}
 if(act==='story'){const order=['seed','water','flower'];if(order[a.picked.length]!==id)return conceptHint('Primero ponemos la semilla. Después la regamos. Por último crece la flor.');a.picked.push(id);}
 if(act==='garden'){const key=`plant${id}`;if(a.picked.includes(key))return;a.picked.push(key);rainbow.push({x:420+Number(id)*170,y:390,life:1,kind:'water'});}
 if(act==='music'){const expected=a.picked.length;if(Number(id)!==expected)return conceptHint('Escuchemos otra vez. Primero grave, después campana'+(a.level>=4?' y luego agudo.':'.'));a.picked.push(`note${id}`);ping([330,550,770][id],.3);}
 if(act==='kite'){const key=`cloud${id}`;if(a.picked.includes(key))return;a.picked.push(key);kite={x:360+Number(id)*220,y:180+Number(id)%2*50};}
 if(act==='picnic'){const order=['blanket','apple','backpack'];if(order[a.picked.length]!==id)return conceptHint('Primero extendemos la manta, después merendamos y al final preparamos mañana.');a.picked.push(id);}
 if(act!=='music')ping(600+a.picked.length*100);persist();const needed={class:1,fruit:a.level<=3?2:3,story:3,garden:a.level<=3?2:3,music:a.level<=3?2:3,kite:3,picnic:3}[act];if(a.picked.length>=needed)advanceSoon();else weekUI();}
function finishDay(){const a=current(),d=day(),res=reward(save,`week-${a.day}`,`week-${a.run}-${a.day}`);addEvidence(`${d.name}: ${d.result}`);let amount=res.amount;const lastDay=a.day===6;amount+=weekBonus(save);save.weekDay=(a.day+1)%7;if(lastDay)save.weekRun++;save.active=null;persist();showReward(`¡Así fue nuestro ${d.name}!`,amount,`${d.result} Después del ${d.name} llega el ${DAYS[save.weekDay]}.${lastDay?' ¡La semana vuelve a empezar!':''}`,()=>navigate('week'),`Descubrir el ${DAYS[save.weekDay]}`);}
function showReward(title,amount,text,next,nextLabel='Volver al pueblo'){celebrating=true;screen=screen;$('#action-list').replaceChildren();$('#scene-progress').hidden=true;for(let i=0;i<24;i++)rainbow.push({x:200+Math.random()*800,y:100+Math.random()*400,life:2+Math.random()*2,kind:'spark',color:colors[i%5]});modal(`<div class="reward-symbol" aria-hidden="true">✳</div><h2 class="party">${safeText(title)}</h2><p>${safeText(text)}</p><div class="reward-amount">+${amount} <span class="coin" aria-label="monedas">✦</span></div><p class="inline-info" style="text-align:center">La recompensa ya está guardada. Las ayudas también cuentan.</p><div class="modal-actions"><button id="reward-next">${safeText(nextLabel)}</button><button id="reward-shop" class="secondary">Elegir un juguete</button><button id="reward-rest" class="secondary">Guardar y descansar</button></div>`);ping(700,.25);setTimeout(()=>ping(900,.3),180);$('#reward-next').onclick=()=>{celebrating=false;closeDialog();next();};$('#reward-shop').onclick=()=>{celebrating=false;closeDialog();screen='map';sceneUI();mapUI();shop();};$('#reward-rest').onclick=()=>{celebrating=false;closeDialog();navigate('map');toast('Todo está guardado. Tu pueblo te espera cuando quieras.');};}

function parkUI(){sceneUI();header('UN RATITO PARA IMAGINAR','Este parque es muy tuyo.','Construye, pinta o simplemente juega. Todo a tu manera.','JUEGO LIBRE · SIN PRISAS');$('#scene-progress').hidden=true;const messages={ball:'Toca el césped para lanzar la pelota. También puedes usar el botón. ¡Te la devuelvo!',block:'Elige un lugar del césped y coloca una pieza. Puedes construir a tu manera.',brush:'Elige un color y dibuja sobre el césped con el dedo o el ratón. Tu dibujo se guarda.',kite:'¡Tu cometa! Toca el cielo o muévela con el dedo para hacerla volar.',flower:'Elige un lugar del césped y planta una flor. Puedes cambiar de color.',drum:'Toca los instrumentos y crea tu propia canción. No hay respuestas correctas.',car:'Coloca piezas de pista sobre el césped. Después toca probar el coche.'};announce(messages[parkMode]||messages.ball);action('Jugar a la pelota',()=>setPark('ball'),{icon:'●',primary:parkMode==='ball'});action('Construir con piezas',()=>setPark('block'),{icon:'▣',primary:parkMode==='block'});action('Pintar libremente',()=>setPark('brush'),{icon:'╱',primary:parkMode==='brush'});
 for(const item of SHOP)if(save.inventory.includes(item.id))action(item.name,()=>setPark(({kite:'kite',flowers:'flower',drums:'drum',track:'car'})[item.id]),{icon:ICONS[item.kind],primary:parkMode===item.kind});
 if(parkMode==='ball')action('Lanzar la pelota',()=>parkInteract(440+Math.random()*350,390+Math.random()*130),{icon:'↗'});
 if(['block','brush','flower','car'].includes(parkMode)){action(({block:'Colocar una pieza',brush:'Pintar una flor',flower:'Plantar una flor',car:'Colocar pista'})[parkMode],()=>parkInteract(400+Math.random()*400,350+Math.random()*180),{icon:'+'});action('Cambiar de color',()=>{color=colors[(colors.indexOf(color)+1)%colors.length];ping(450);toast('¡Otro color!');},{icon:'◉'});}
 if(parkMode==='kite')action('Hacer volar la cometa',()=>parkInteract(300+Math.random()*600,150+Math.random()*180),{icon:'↗'});
 if(parkMode==='drum')for(let i=0;i<3;i++)action(['Sonido grave','Campana','Sonido agudo'][i],()=>playNote(i),{icon:'♫'});
 if(parkMode==='car')action('Probar el coche',driveToy,{icon:'↗'});
 action('Ver juguetes nuevos',shop,{icon:'◇'});$('#scene-caption').textContent='Puedes volver al pueblo cuando quieras';}
function setPark(mode){parkMode=mode;selected=null;parkUI();}
function playNote(i){ping([260,440,660][i],.5);note=i;rainbow.push({x:420+i*180,y:350,life:1,kind:'note'});}
function driveToy(){if(save.park.track.length<2)return toast('Coloca al menos dos piezas de pista.');if(animation)return;animation={kind:'toy',elapsed:0,duration:4,callback:()=>{animation=null;ping();}};}
function parkInteract(x,y){x=Math.max(200,Math.min(1030,x));y=Math.max(240,Math.min(640,y));
 if(parkMode==='ball'){ball.vx=(x-ball.x)*1.2;ball.vy=(y-ball.y)*1.2-120;ping(450);}
 if(parkMode==='kite'){kite={x,y:Math.max(110,y-120)};rainbow.push({x,y,life:.7,kind:'spark',color:'#e5b76b'});}
 if(parkMode==='block')save.park.blocks.push({x,y,color});
 if(parkMode==='flower')save.park.flowers.push({x,y,color});
 if(parkMode==='brush')save.park.paint.push({x,y,color});
 if(parkMode==='car')save.park.track.push({x,y,color});
 if(parkMode==='drum')playNote(x<500?0:x<720?1:2);
 for(const k of ['blocks','flowers','paint','track'])save.park[k]=save.park[k].slice(-100);laterSave();}
function toySVG(kind){const shapes={kite:'<path d="M50 6 82 37 50 69 18 37Z" fill="#e3b565"/><path d="M50 6V37H18Z" fill="#8fb3a9"/><path d="M50 37H82L50 69Z" fill="#d88c6e"/><path d="M50 69q15 9 1 17" fill="none" stroke="#a49574" stroke-width="2"/>',flower:'<path d="M37 55h30l-4 27H41Z" fill="#ce9873"/><path d="M52 56V27" stroke="#87a575" stroke-width="4"/><g fill="#e6b263"><circle cx="42" cy="24" r="9"/><circle cx="54" cy="14" r="9"/><circle cx="65" cy="25" r="9"/><circle cx="60" cy="37" r="9"/><circle cx="45" cy="37" r="9"/></g><circle cx="53" cy="27" r="7" fill="#f6d99a"/>',drum:'<path d="M18 33h64v33q-32 25-64 0Z" fill="#d4a063"/><ellipse cx="50" cy="33" rx="32" ry="15" fill="#f6e2b2"/><path d="m24 52 12 20 14-21 15 21 13-20" fill="none" stroke="#f4d59b" stroke-width="3"/><path d="m22 12 25 16m30-16L55 28" stroke="#839b82" stroke-width="5"/>',car:'<rect x="15" y="37" width="73" height="30" rx="8" fill="#cd8c67"/><path d="M31 38V20h38v18" fill="#e3b87c"/><path d="M37 25h25v13H37Z" fill="#b5ceca"/><g fill="#637562"><circle cx="30" cy="68" r="10"/><circle cx="74" cy="68" r="10"/></g>'};return `<svg viewBox="0 0 100 95" aria-hidden="true">${shapes[kind]}</svg>`;}
function shop(){modal(`<span class="eyebrow">LA TIENDA DE VILLACHISPA</span><h2>Un juguete, mil historias.</h2><p>Tienes <b>${save.coins} monedas</b>. Cada juguete es tuyo para siempre y puedes usarlo en el parque.</p><div class="shop-grid">${SHOP.map(item=>`<div class="shop-item">${toySVG(item.kind)}<b>${item.name}</b><p>${item.description}</p><button data-buy="${item.id}" ${!save.inventory.includes(item.id)&&save.coins<item.price?'disabled':''}>${save.inventory.includes(item.id)?'Jugar en mi parque':`${item.price} monedas · Comprar`}</button></div>`).join('')}</div><p class="inline-info">La pelota, las piezas y la pintura siempre están disponibles gratis.</p>`);content.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const id=b.dataset.buy;if(save.inventory.includes(id)){closeDialog();navigate('park');setPark(({kite:'kite',flowers:'flower',drums:'drum',track:'car'})[id]);return;}const res=purchase(save,id);if(res.ok){persist();ping(900);shop();toast(`¡${res.item.name} ya es tuyo!`);}else toast(res.reason);});}
function ageModal(){modal(`<span class="eyebrow">CADA NIÑO, SU CAMINO</span><h2>¿Cómo quieres explorar?</h2><p>El nivel adapta las próximas aventuras. La que ya empezaste mantiene sus ayudas y se puede terminar sin prisas.</p><div class="age-grid">${[3,4,5,6].map((n,i)=>`<button data-age="${n}" class="${save.age===n?'active':''}">${n} años<small>${['Descubro','Exploro','Resuelvo','Puente a Primaria'][i]}</small></button>`).join('')}</div>`);content.querySelectorAll('[data-age]').forEach(b=>b.onclick=()=>{save.age=Number(b.dataset.age);persist();closeDialog();toast('Nivel guardado para las próximas aventuras.');});}
function adultModal(){modal(`<span class="eyebrow">PARA ACOMPAÑAR LA AVENTURA</span><h2>El rincón de los mayores.</h2><p>Esta primera versión incluye bomberos, siete jornadas del calendario y un parque creativo. La progresión por edades es una propuesta adaptable, no una programación oficial por curso.</p><label class="setting-row">Voz y efectos <input id="setting-sound" type="checkbox" ${save.settings.sound?'checked':''}></label><label class="setting-row">Modo tranquilo <input id="setting-quiet" type="checkbox" ${save.settings.quiet?'checked':''}></label><label class="setting-row">Festivo en el calendario <input id="setting-holiday" type="checkbox" ${save.settings.holiday?'checked':''}></label><p class="inline-info">La voz usa la síntesis del navegador. Depende de las voces españolas disponibles y puede requerir conexión. No hay todavía doblaje grabado. Las instrucciones también se muestran y se representan visualmente.</p><div class="modal-actions"><button id="adult-level">Cambiar nivel</button><button id="export-save" class="secondary">Guardar una copia</button><button id="import-save" class="secondary">Recuperar una copia</button></div><input type="file" id="import-file" accept="application/json,.json" hidden><p class="inline-info">La partida se guarda solo en este navegador. No se sincroniza con otros dispositivos. Conserva una copia antes de borrar sus datos.</p><h3>Lo que hemos practicado</h3>${save.evidence.length?`<ul>${save.evidence.slice(-5).map(e=>`<li class="inline-info">${safeText(e.text)} ${e.assisted?'Con ayuda.':''}</li>`).join('')}</ul>`:'<p class="inline-info">Aquí aparecerán las aventuras que hayáis terminado.</p>'}<div class="modal-actions"><button id="offline-info" class="secondary">Instalar y jugar sin conexión</button><button id="reset-mission" class="secondary">Reiniciar aventura actual</button></div><p class="inline-info">Sin anuncios ni pagos. El juego complementa la conversación, el movimiento y el juego fuera de pantalla.</p>`);
 for(const name of ['sound','quiet','holiday'])$(`#setting-${name}`).onchange=e=>{save.settings[name]=e.target.checked;if(name==='sound'&&!e.target.checked)window.speechSynthesis?.cancel();persist();if(screen==='week'&&current())weekUI();};$('#adult-level').onclick=ageModal;$('#export-save').onclick=()=>{const blob=new Blob([JSON.stringify(save,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='villachispa-partida.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);};$('#import-save').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1000000)return toast('La copia es demasiado grande.');try{const imported=validateSave(JSON.parse(await file.text()));modal('<h2>¿Recuperar esta partida?</h2><p>Reemplazará la partida de este navegador. Puedes guardar antes una copia de la partida actual.</p><div class="modal-actions"><button id="confirm-import">Recuperar partida</button><button id="cancel-import" class="secondary">Cancelar</button></div>');$('#confirm-import').onclick=()=>{save=imported;animation=null;persist();closeDialog();navigate('map');toast('Tu partida está recuperada.');};$('#cancel-import').onclick=adultModal;}catch{toast('No se pudo leer esa copia de partida.');}};$('#offline-info').onclick=installationInfo;$('#reset-mission').onclick=()=>{if(!save.active)return toast('No hay una aventura en marcha.');modal('<h2>¿Volver al comienzo?</h2><p>Solo se reiniciará la aventura actual. Conservarás tus monedas, juguetes y aventuras terminadas.</p><div class="modal-actions"><button id="confirm-restart">Reiniciar aventura</button><button id="cancel-restart" class="secondary">Seguir como estaba</button></div>');$('#confirm-restart').onclick=()=>{save.active=null;animation=null;persist();closeDialog();navigate(screen==='fire'?'fire':screen==='week'?'week':'map');};$('#cancel-restart').onclick=adultModal;};}
function installationInfo(){modal(`<h2>Tu pueblo, más a mano.</h2><p><b>Android:</b> abre el menú del navegador y busca «Instalar aplicación» o «Añadir a pantalla de inicio».</p><p><b>iPhone o iPad:</b> abre el juego en Safari, pulsa Compartir y elige «Añadir a pantalla de inicio».</p><p>Cuando el indicador inferior diga «Juego listo sin conexión», esta versión completa estará descargada. La voz del navegador puede seguir necesitando red. El sistema puede borrar almacenamiento si necesita espacio.</p><div class="modal-actions"><button id="install-now">${deferredInstall?'Instalar ahora':'Entendido'}</button><button id="check-offline" class="secondary">Comprobar descarga</button></div>`);$('#install-now').onclick=async()=>{if(deferredInstall){await deferredInstall.prompt();deferredInstall=null;}closeDialog();};$('#check-offline').onclick=()=>checkOffline(true);}

