 if(['equipo','depósito'].includes(step)){art.road([[0,520],[600,640],[1250,360]],94);art.building(710,300,'fire',1.35);art.truck(670,470,1.65);art.person(910,471,1.35,0,true);art.label('Equipo de bomberos',760,170,'NOS PREPARAMOS JUNTOS');if(step==='equipo'){const items=fireItems();items.forEach((id,i)=>{const x=280+i*175,y=610;if(a.picked.includes(id)){art.item(id,570+i*55,418,.55);return;}art.ellipse(x,y+8,62,30,'#f3edd5');if(selected===id)art.ring(x,y+8,65);art.item(id,drag?.id===id?drag.x:x,drag?.id===id?drag.y:y,1.25);art.text(names[id],x,y+52,17);hit(id,x,y,66,()=>choose(id));});art.ring(670,493,110,time);hit('truck',670,470,150,putEquipment);}else{art.rect(320,330,83,180,'#e7dfc6',15);art.rect(335,350,53,140,'#b4c7b3',7);art.rect(335,490-hydration*140,53,hydration*140,'#8fb7b5',7);art.line([[327,367],[397,367]],'#b78c57',4);art.text('AGUA',360,314,13);art.line([[400,480],[478,530],[510,500]],'#7f9d8c',12);art.rect(450,365,20,140,'#a39777',8);art.rect(430,440-hydration*70,60,23,'#d69e62',9);hit('lever',460,450,70,fillTank);}}
 if(step==='camino'){art.road([[140,620],[390,520],[560,320],[960,390]],85);if(a.level>=5){art.road([[390,520],[640,630],[950,390]],60);art.line([[660,615],[765,565]],'#b9956e',55);art.line([[670,580],[755,620]],'#cf9275',9);art.line([[680,620],[750,575]],'#cf9275',9);art.label('Cerrado',728,663,'PUENTE DE MADERA');}art.path([[580,250],[660,285],[700,380],[610,360]],'#b4d3c7');art.line([[575,303],[662,336]],'#e8dbb8',70);art.line([[577,287],[664,320]],'#c3b290',6);art.line([[577,319],[664,352]],'#c3b290',6);art.building(1000,363,'home',.8);let p=animation?.kind==='drive-fire'?animation.elapsed/animation.duration:0;const points=[[140,620],[390,520],[560,320],[960,390]];const pos=along(points,p);art.truck(pos.x,pos.y,1);art.label('La granja',994,434,'EL EQUIPO NOS ESPERA');art.ring(960,430,60);hit('route',960,410,110,()=>driveFire(0));}
 if(['animales','agua','cuidado','recuerdos'].includes(step)){art.road([[0,540],[270,470],[640,580],[1200,390]],75);art.building(600,330,'home',1.25);art.truck(240,490,1.2);art.fence(800,430,6);art.fence(813,560,6);art.ellipse(920,510,110,43,'#aeca92');art.label('Corral seguro',935,620,'JUNTOS Y TRANQUILOS');art.person(735,424,1.05,0,true);for(let i=0;i<fireCount();i++){const water=a.water[i]||0;if(water<1){let p=1-water;if(animation?.kind==='spray'&&animation.index===i)p*=1-animation.elapsed/animation.duration;art.fire(510+i*65,325+i%2*20,Math.max(.06,p),save.settings.quiet?0:time);}}
 for(let i=0;i<animalCount();i++){const id=`animal${i}`,rescued=step!=='animales'||a.picked.includes(id);let x=rescued?865+i*95:490+i*140,y=rescued?505+i*25:480+i*30;if(animation?.kind==='rescue'&&animation.id===id){const p=animation.elapsed/animation.duration;x=x+(865+i*95-x)*p;y=y+(505+i*25-y)*p;}if(drag?.id===id){x=drag.x;y=drag.y;}if(selected===id)art.ring(x,y+5,48);art.animal(x,y,i?'cat':'sheep',1.25);if(step==='animales'&&!a.picked.includes(id))hit(id,x,y-16,66,()=>choose(id));if(step==='cuidado'){art.ellipse(x+27,y+13,25,11,a.picked.includes(`care${i}`)?'#aaccc2':'#e1d7b9');hit(`care${i}`,x,y,65,()=>careAnimal(i));}}
 if(step==='animales'){art.ring(920,530,100);hit('pen',930,520,120,rescue);}
 if(step==='agua'){art.person(400,560,1.25,0,true);art.line([[270,480],[310,540],[400,535]],'#8ca490',13);art.line([[393,536],[430,515]],'#c5b694',13);art.label('Zona segura',370,647,'EL EQUIPO TE ACOMPAÑA');for(let i=0;i<fireCount();i++)if(a.water[i]<1){art.ring(510+i*65,340+i%2*20,32);hit(`fire${i}`,510+i*65,300+i%2*20,52,()=>sprayTarget(i));}const spray=animation?.kind==='spray'?{x:510+animation.index*65,y:300+animation.index%2*20}:liveAction?pointer:null;if(spray){art.line([[425,522],[spray.x,spray.y]],'#cce9e7b0',20);art.line([[425,522],[spray.x+5,spray.y]],'#a7ced3',8);for(let j=0;j<7;j++)art.ellipse(spray.x+Math.sin(time*9+j)*20,spray.y+Math.cos(time*7+j)*12,4,5,'#dcefe4');}}
 if(step==='cuidado')art.item('water',660,605,1.3);
 if(step==='recuerdos'){['helmet','car','water'].forEach((id,i)=>{const x=340+i*250;art.rect(x-88,510,176,145,a.picked.includes(`memory${i}`)?'#d5e0bd':'#fff3d7',18);art.item(id,x,575,1.2);art.text(['Preparar','Llegar','Cuidar'][i],x,635,18);hit(`memory${i}`,x,577,90,()=>memory(i));});}
 }
