function along(points,p){p=Math.max(0,Math.min(.99999,p));const i=Math.min(points.length-2,Math.floor(p*(points.length-1))),f=p*(points.length-1)-i;return {x:points[i][0]+(points[i+1][0]-points[i][0])*f,y:points[i][1]+(points[i+1][1]-points[i][1])*f};}
function drawWeek(){art.ground();backgroundTrees();const a=current();if(!a)return;const d=day();art.road([[0,520],[330,620],[620,440],[950,480],[1230,330]],70);if(a.stage<2){art.building(280,350,'home',1);art.building(890,330,weekIsSchool()?'school':'shop',1);if(!weekIsSchool()){art.item('kite',860,430,.8);art.label('El parque',920,430,'UN DÍA POR DESCUBRIR');}else art.label('El colegio',893,405,'VAMOS JUNTOS');}
 for(let i=0;i<7;i++){const x=295+i*96;art.rect(x-38,90,77,69,i===a.day?'#4f8064':save.completed[`week-${i}`]?'#d4bd8c':'#f7efd8',13);art.text(DAYS[i].slice(0,3).toUpperCase(),x,113,13,i===a.day?'#fff6df':'#75846a');art.text(i<5?'⌂':'☀',x,140,20,i===a.day?'#fff6df':'#8c9b7a');}art.text(`${DAYS[a.day].toUpperCase()}${a.day<5&&save.settings.holiday?' · FESTIVO':''}`,620,205,25,'#4b7055');
 if(a.stage===0){art.person(580,450,1.3);art.rect(750,480,155,95,'#bc9b6e',22);art.rect(767,467,120,40,'#d7be89',15);art.line([[790,470],[790,445],[862,445],[862,470]],'#b39871',9);art.label(d.goal==='mochila'?'Mi mochila':d.goal==='carrito'?'Mi carrito':'Mi cesta',825,611);art.ring(825,563,90);hit('bag',825,520,110,weekPack);weekItems().forEach((id,i)=>{const x=300+i*155,y=570;if(a.picked.includes(id)){art.item(id,785+i*35,501,.5);return;}art.ellipse(x,y+15,57,27,'#f3e9cd');if(selected===id)art.ring(x,y+10,59);art.item(id,drag?.id===id?drag.x:x,drag?.id===id?drag.y:y,1.15);art.text(names[id],x,y+58,17);hit(id,x,y,65,()=>choose(id));});}
 if(a.stage===1){const p=animation?.kind==='week-walk'?animation.elapsed/animation.duration:0;const pos=along([[340,455],[500,525],[680,450],[875,440]],p);art.person(pos.x,pos.y,1.4,p>0?time*8:0);art.ring(890,475,65);hit('walk',890,450,110,weekWalk);}
 if(a.stage===2)drawDayActivity(d.activity);}
function drawDayActivity(act){const a=current();if(act==='class'){art.box(690,470,160,90,75,['#d5b781','#b69f73','#edd9a6']);art.person(590,480,1.3);if(!a.picked.includes('book')){art.item('book',drag?.id==='book'?drag.x:350,drag?.id==='book'?drag.y:530,1.5);hit('book',350,530,75,()=>choose('book'));if(selected==='book')art.ring(350,550,65);}art.ring(725,438,85);hit('desk',735,440,110,weekTask);art.label('Un libro para descubrir',720,580);}
 if(act==='fruit'){art.box(575,500,220,90,50,['#d8bd8d','#bfa77c','#efdaac']);const n=a.level<=3?2:3;for(let i=0;i<n;i++){const x=380+i*210;art.person(x,450,1.3);art.ellipse(x,515,47,23,'#f8edd1');if(a.picked.includes(`fruit${i}`))art.item('apple',x,505,.7);else{art.ring(x,516,48);hit(`fruit${i}`,x,500,75,()=>weekTask(i));}art.text(['Luma','Nico','Sol'][i],x,580,17);}art.item('apple',600,633,1.3);}
 if(act==='story'){const ids=['flower','seed','water'];for(let i=0;i<3;i++){const id=ids[i],x=350+i*245;art.rect(x-90,325,180,205,a.picked.includes(id)?'#d3deba':'#fcf1d7',18);art.item(id,x,420,1.6);art.text(({flower:'La flor',seed:'La semilla',water:'El agua'})[id],x,500,18);hit(id,x,425,95,()=>weekTask(id));if(a.picked.includes(id))art.text(String(a.picked.indexOf(id)+1),x,358,24,'#52825e');}art.label('Primero · después · al final',605,623);}
 if(act==='garden'){for(let i=0;i<(a.level<=3?2:3);i++){const x=410+i*180,y=440+i%2*45;art.path([[x-70,y],[x,y-35],[x+70,y],[x,y+35]],'#bcaa7e');const grown=a.picked.includes(`plant${i}`);if(grown){art.flower(x-15,y-6,'#e6ad72',2);art.flower(x+20,y+3,'#d9a2a2',1.5);}else{art.line([[x,y],[x,y-25]],'#839b66',6);art.ellipse(x-11,y-20,14,6,'#a4ba7e');art.ellipse(x+12,y-30,14,6,'#a4ba7e');art.ring(x,y+10,60);}hit(`plant${i}`,x,y,75,()=>weekTask(i));}art.item('water',drag?.id==='water'?drag.x:330,drag?.id==='water'?drag.y:630,1.5);hit('water',330,630,65,()=>{selected='water';toast('Lleva la regadera a una planta.');});art.person(895,540,1.4);}
 if(act==='music'){for(let i=0;i<3;i++){const x=410+i*190;art.ellipse(x,480,70,32,'#d8dfb6');art.item('drum',x,427,1.55);art.text(['GRAVE','CAMPANA','AGUDO'][i],x,535,15);if(a.picked.includes(`note${i}`))art.text('✓',x,355,32,'#58845e');hit(`note${i}`,x,435,80,()=>weekTask(i));}art.label('Escucha · toca · inventa',605,623);}
 if(act==='kite'){art.person(600,580,1.5);for(let i=0;i<3;i++){const x=360+i*220,y=300+i%2*50;art.ellipse(x,y,58,21,a.picked.includes(`cloud${i}`)?'#dcebd0':'#fff8e7');art.ellipse(x-20,y-10,25,22,'#fff8e7');art.ellipse(x+15,y-13,28,25,'#fff8e7');art.text(a.picked.includes(`cloud${i}`)?'✓':String(i+1),x,y+3,18,'#7d9273');hit(`cloud${i}`,x,y,75,()=>weekTask(i));}art.line([[610,530],[kite.x,kite.y+25]],'#b7a579',2);art.item('kite',kite.x,kite.y+Math.sin(time)*5,1.45);}
 if(act==='picnic'){if(a.picked.includes('blanket')){art.path([[390,430],[660,365],[860,475],[575,550]],'#e6b58c');for(let i=0;i<5;i++)art.line([[420+i*60,430-i*14],[600+i*55,525-i*14]],'#efd7b2',9);}else art.item('book',450,500,1.2);if(a.picked.includes('apple')){art.item('apple',600,460,.9);art.item('bottle',680,460,.9);}if(a.picked.includes('backpack')){art.rect(850,480,80,70,'#c4a875',15);art.item('book',880,490,.6);}for(const [id,x,y]of [['blanket',450,500],['apple',650,470],['backpack',890,510]])hit(id,x,y,90,()=>weekTask(id));art.person(400,600,1.4);art.person(760,580,1.2);art.label('¡Mañana es lunes!',870,620);}}
function drawPark(){art.ground();backgroundTrees();art.road([[0,640],[220,680],[490,660],[1100,700],[1250,580]],65);art.fence(270,235,12);art.tree(900,315,1.45,1);art.tree(250,370,1);art.person(590,610,1.3);art.label('Tu rincón para imaginar',590,167,'TODO EMPIEZA CON UNA IDEA');for(const p of save.park.paint)art.ellipse(p.x,p.y,8,6,p.color+'aa');for(const p of save.park.flowers)art.flower(p.x,p.y,p.color,1.2);for(const p of [...save.park.blocks].sort((a,b)=>a.y-b.y))art.item('block',p.x,p.y,.9,p.color);if(save.park.track.length){art.line(save.park.track.map(p=>[p.x,p.y]),'#bbac87',36);art.line(save.park.track.map(p=>[p.x,p.y]),'#f2e3bd',25);if(animation?.kind==='toy'){const pos=along(save.park.track.map(p=>[p.x,p.y]),animation.elapsed/animation.duration);art.item('car',pos.x,pos.y,.8);}else{const p=save.park.track[0];art.item('car',p.x,p.y,.8);}}
 art.item('ball',ball.x,ball.y,1.1);if(parkMode==='kite'){art.line([[600,568],[kite.x,kite.y+20]],'#afa376',2);art.item('kite',kite.x,kite.y+Math.sin(time)*8,1.35);}if(parkMode==='drum')for(let i=0;i<3;i++){art.item('drum',430+i*170,420,1.4);hit(`drum${i}`,430+i*170,420,75,()=>playNote(i));}if(parkMode==='brush'||parkMode==='flower'||parkMode==='block')colors.forEach((c,i)=>{art.ellipse(410+i*85,670,28,25,c);if(c===color)art.ring(410+i*85,670,32);hit(`color${i}`,410+i*85,670,34,()=>{color=c;ping(440);});});}
function render(){ctx.clearRect(0,0,1200,760);hits=[];if(screen==='map'||screen==='shop')drawMap();if(screen==='fire')drawFire();if(screen==='week')drawWeek();if(screen==='park')drawPark();for(const p of rainbow){ctx.globalAlpha=Math.min(1,p.life);if(p.kind==='note')art.text('♫',p.x,p.y-((1-p.life)*55),45,'#b8945f');else if(p.kind==='water'){for(let j=0;j<9;j++)art.ellipse(p.x+Math.sin(j)*35,p.y-j*6,4,9,'#accdc4');}else if(p.kind==='spark'){art.text('✦',p.x,p.y-(3-p.life)*12,20,p.color||'#e1b368');}ctx.globalAlpha=1;}if(drag){ctx.globalAlpha=.35;art.ellipse(drag.x,drag.y+30,35,12,'#7b9570');ctx.globalAlpha=1;}if(selected&&!drag&&['helmet','hose','cone','book','bottle','apple','water','seed','kite','drum'].includes(selected))art.item(selected,1070,650,.7);}

function canvasPoint(e){const r=canvas.getBoundingClientRect(),scale=Math.min(r.width/1200,r.height/760),ox=(r.width-1200*scale)/2,oy=(r.height-760*scale)/2;return{x:(e.clientX-r.left-ox)/scale,y:(e.clientY-r.top-oy)/scale};}
function closestHit(p){return [...hits].reverse().find(h=>Math.hypot((p.x-h.x),p.y-h.y)<h.r);}
canvas.addEventListener('pointerdown',e=>{if(dialog.open||animation)return;const p=canvasPoint(e);pointer=p;const h=closestHit(p);canvas.setPointerCapture(e.pointerId);if(screen==='park'){if(h){h.fn();return;}parkInteract(p.x,p.y);drag={id:'park',...p};return;}const itemScene=(screen==='fire'&&['equipo','animales','depósito'].includes(fireStep()))||(screen==='week'&&(current().stage===0||(current().stage===2&&['class','garden'].includes(day().activity))));if(h&&itemScene&&(['helmet','hose','cone','book','bottle','apple','water','seed','kite','drum','lever'].includes(h.id)||h.id.startsWith('animal'))){drag={id:h.id,...p,startX:p.x,startY:p.y};selected=h.id;return;}if(screen==='fire'&&fireStep()==='agua'){const target=h?.id.startsWith('fire')?Number(h.id.slice(4)):null;if(target!==null){sprayTarget(target);return;}liveAction=true;return;}if(h)h.fn();else if(screen==='map'){player.target={x:Math.min(1020,Math.max(150,p.x)),y:Math.min(650,Math.max(380,p.y))};}});
canvas.addEventListener('pointermove',e=>{const p=canvasPoint(e);pointer=p;if(drag){drag.x=p.x;drag.y=p.y;if(drag.id==='park'&&['brush','kite'].includes(parkMode))parkInteract(p.x,p.y);}canvas.style.cursor=closestHit(p)?'pointer':screen==='park'?'crosshair':'default';});
canvas.addEventListener('pointerup',e=>{liveAction=false;if(!drag)return;const p=canvasPoint(e),id=drag.id,moved=Math.hypot(p.x-drag.startX,p.y-drag.startY)>20;drag=null;if(id==='park'){persist();return;}const h=closestHit(p);if(id==='lever'){fillTank();return;}if(!moved){if(id==='water'&&screen==='week'&&current().stage===2){selected='water';toast('Ahora toca una planta para regarla.');}else choose(id);return;}selected=id;if(screen==='fire'){if(fireStep()==='equipo'&&h?.id==='truck')putEquipment();else if(fireStep()==='animales'&&h?.id==='pen')rescue();else hint('Puedes tocar el objeto y después su destino.');}else if(screen==='week'){if(current().stage===0&&h?.id==='bag')weekPack();else if(current().stage===2&&day().activity==='class'&&h?.id==='desk')weekTask();else if(current().stage===2&&day().activity==='garden'&&h?.id.startsWith('plant'))weekTask(Number(h.id.slice(5)));else hint('Puedes tocar el objeto y después su destino.');}});
canvas.addEventListener('pointercancel',()=>{drag=null;pointer=null;liveAction=false;});
document.addEventListener('visibilitychange',()=>{if(document.hidden){liveAction=false;drag=null;window.speechSynthesis?.cancel();persist();last=0;}});
window.addEventListener('pagehide',persist);window.addEventListener('blur',()=>{liveAction=false;drag=null;persist();});
function loop(stamp){const dt=last?Math.min(.04,(stamp-last)/1000):0;last=stamp;if(!document.hidden&&!dialog.open){time+=save.settings.quiet?0:dt;if(animation){animation.elapsed+=dt;if(animation.kind==='tank')hydration=Math.min(1,animation.elapsed/animation.duration);if(animation.elapsed>=animation.duration){const cb=animation.callback;cb();}}
 if(player.target){const dx=player.target.x-player.x,dy=player.target.y-player.y,dist=Math.hypot(dx,dy);if(dist<5)player.target=null;else{player.x+=dx/dist*dt*150;player.y+=dy/dist*dt*150;}}
 if(liveAction&&screen==='fire'&&current()&&fireStep()==='agua'&&pointer){for(let i=0;i<fireCount();i++)if(Math.hypot(pointer.x-(510+i*65),pointer.y-(300+i%2*20))<65&&current().water[i]<1){current().water[i]=Math.min(1,current().water[i]+dt*.8);laterSave();if(current().water.slice(0,fireCount()).every(v=>v>=1)){liveAction=false;persist();advanceSoon();}}}
 if(screen==='park'){ball.x+=ball.vx*dt;ball.y+=ball.vy*dt;ball.vx*=Math.exp(-dt*2);ball.vy*=Math.exp(-dt*2);if(ball.x<240||ball.x>1000)ball.vx*=-.8;if(ball.y<280||ball.y>590)ball.vy*=-.8;ball.x=Math.max(230,Math.min(1010,ball.x));ball.y=Math.max(270,Math.min(600,ball.y));}rainbow.forEach(p=>p.life-=dt);rainbow=rainbow.filter(p=>p.life>0);render();}requestAnimationFrame(loop);}

document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));$('.brand').onclick=e=>{e.preventDefault();navigate('map');};$('#adult-button').onclick=adultModal;$('#age-button').onclick=ageModal;$('#sound-button').onclick=()=>{save.settings.sound=!save.settings.sound;persist();if(!save.settings.sound)window.speechSynthesis?.cancel();else speak('¡Hola! ¿Vamos a jugar?');};$('#repeat-button').onclick=()=>speak($('#guide-message').textContent);$('#help-button').onclick=()=>{if(current()&&['fire','week'].includes(screen)){current().assisted=true;persist();}hint($('#guide-message').textContent);};dialog.addEventListener('close',()=>{if(celebrating){celebrating=false;navigate('map');}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dialog.open){navigate('map');}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('#install-button').hidden=false;});$('#install-button').onclick=installationInfo;
async function checkOffline(showToast=false){if(!navigator.serviceWorker?.controller){if(showToast)toast('La descarga se prepara. Espera unos segundos y vuelve a comprobar.');return;}const channel=new MessageChannel();channel.port1.onmessage=e=>{const ready=e.data?.ready;$('#connection-status').textContent=ready?'Juego listo sin conexión · voz según dispositivo':'Preparando descarga sin conexión';if(showToast)toast(ready?'El juego está descargado. La voz depende de tu dispositivo.':'La descarga no está completa. Mantén el juego abierto con conexión.');};navigator.serviceWorker.controller.postMessage({type:'CHECK_CACHE'},[channel.port2]);}
async function boot(){await load();if(save.active){const max=save.active.type==='fire'?fireSteps(save.active.level).length:3;if(save.active.stage>=max)save.active=null;}updateBalance();navigate('map');requestAnimationFrame(loop);if('serviceWorker'in navigator){try{await navigator.serviceWorker.register('./sw.js',{scope:'./'});navigator.serviceWorker.addEventListener('controllerchange',()=>checkOffline());await navigator.serviceWorker.ready;checkOffline();}catch{$('#connection-status').textContent='Guardado local · instalación no disponible';}}}
boot();

